import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type CheckboxCheckedState = boolean | "indeterminate";
export type CheckboxSize = "sm" | "md" | "lg";
export type CheckboxVariant = "classic" | "soft" | "dot" | "toggle";

export interface CheckboxProps
  extends Omit<
    React.InputHTMLAttributes<HTMLInputElement>,
    "checked" | "defaultChecked" | "onChange" | "size" | "type"
  > {
  checked?: CheckboxCheckedState;
  defaultChecked?: CheckboxCheckedState;
  onCheckedChange?: (
    checked: boolean,
    event: React.ChangeEvent<HTMLInputElement>,
  ) => void;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  checkboxSize?: CheckboxSize;
  variant?: CheckboxVariant;
  fullWidth?: boolean;
  containerClassName?: string;
  controlClassName?: string;
  labelClassName?: string;
  descriptionClassName?: string;
}

export interface CheckboxGroupProps
  extends React.HTMLAttributes<HTMLFieldSetElement> {
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  children: React.ReactNode;
}

export interface CheckboxCardProps extends CheckboxProps {
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
}

const controlSizes: Record<CheckboxSize, string> = {
  sm: "size-[15px]",
  md: "size-[18px]",
  lg: "size-[21px]",
};

const toggleSizes: Record<CheckboxSize, string> = {
  sm: "h-[18px] w-[30px]",
  md: "h-[22px] w-[38px]",
  lg: "h-[26px] w-[46px]",
};

const knobSizes: Record<CheckboxSize, string> = {
  sm: "size-3.5",
  md: "size-[18px]",
  lg: "size-[22px]",
};

const knobCheckedTravel: Record<CheckboxSize, string> = {
  sm: "translate-x-3",
  md: "translate-x-4",
  lg: "translate-x-5",
};

const knobIndeterminateTravel: Record<CheckboxSize, string> = {
  sm: "translate-x-1.5",
  md: "translate-x-2",
  lg: "translate-x-2.5",
};

const rowGap: Record<CheckboxSize, string> = {
  sm: "gap-2.5",
  md: "gap-3",
  lg: "gap-3.5",
};

const labelSizes: Record<CheckboxSize, string> = {
  sm: "text-[13px]",
  md: "text-sm",
  lg: "text-[15px]",
};

const controlOffset: Record<CheckboxSize, string> = {
  sm: "mt-px",
  md: "mt-0.5",
  lg: "mt-0.5",
};

const focusRing = cn(
  "peer-focus-visible:outline-none",
  "peer-focus-visible:ring-2 peer-focus-visible:ring-[color-mix(in_srgb,var(--foreground)_18%,transparent)]",
  "peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-[var(--background)]",
);

const smoothControlTransition =
  "transition-[background-color,border-color,box-shadow,opacity] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

const smoothMarkTransition =
  "transition-[opacity,transform] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

function getControlClasses({
  variant,
  checked,
  indeterminate,
  disabled,
  error,
  checkboxSize,
}: {
  variant: CheckboxVariant;
  checked: boolean;
  indeterminate: boolean;
  disabled?: boolean;
  error?: React.ReactNode;
  checkboxSize: CheckboxSize;
}) {
  const active = checked || indeterminate;

  if (variant === "toggle") {
    return cn(
      "relative inline-flex shrink-0 items-center rounded-full p-0.5",
      "border border-transparent",
      smoothControlTransition,
      "bg-[color-mix(in_srgb,var(--foreground)_8%,var(--background))]",
      "shadow-[inset_0_1px_2px_rgba(0,0,0,0.06)]",
      "dark:bg-[color-mix(in_srgb,var(--foreground)_14%,var(--background))]",
      "dark:shadow-[inset_0_1px_2px_rgba(0,0,0,0.35)]",
      focusRing,
      !disabled &&
        "group-hover/checkbox:bg-[color-mix(in_srgb,var(--foreground)_12%,var(--background))]",
      active &&
        cn(
          "border-[color-mix(in_srgb,var(--foreground)_10%,transparent)]",
          "bg-[var(--foreground)]",
          "shadow-[0_1px_2px_rgba(0,0,0,0.10),0_0_0_1px_rgba(0,0,0,0.04)]",
          "dark:shadow-[0_1px_3px_rgba(0,0,0,0.45),0_0_0_1px_rgba(255,255,255,0.06)]",
        ),
      error && "ring-1 ring-red-500/35",
      disabled && "cursor-not-allowed opacity-40",
      toggleSizes[checkboxSize],
    );
  }

  if (variant === "soft") {
    return cn(
      "relative grid shrink-0 place-items-center rounded-[7px] border",
      smoothControlTransition,
      "border-[var(--border-strong)] bg-[color-mix(in_srgb,var(--foreground)_3.5%,var(--background))]",
      "shadow-[0_1px_1px_rgba(0,0,0,0.03)]",
      "dark:shadow-[0_1px_2px_rgba(0,0,0,0.28)]",
      focusRing,
      !disabled &&
        "group-hover/checkbox:border-[color-mix(in_srgb,var(--foreground)_20%,transparent)] group-hover/checkbox:bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
      active &&
        cn(
          "border-[color-mix(in_srgb,var(--foreground)_28%,transparent)]",
          "bg-[color-mix(in_srgb,var(--foreground)_11%,var(--background))]",
          "shadow-[0_1px_2px_rgba(0,0,0,0.05)]",
          "dark:bg-[color-mix(in_srgb,var(--foreground)_16%,var(--background))]",
        ),
      error &&
        "border-red-500/55 bg-red-500/[0.06] shadow-[0_0_0_1px_rgba(239,68,68,0.08)]",
      disabled && "cursor-not-allowed opacity-40",
      controlSizes[checkboxSize],
    );
  }

  if (variant === "dot") {
    return cn(
      "relative grid shrink-0 place-items-center rounded-full border",
      smoothControlTransition,
      "border-[var(--border-strong)] bg-[var(--background)]",
      "shadow-[0_1px_1px_rgba(0,0,0,0.03)]",
      "dark:shadow-[0_1px_2px_rgba(0,0,0,0.28)]",
      focusRing,
      !disabled &&
        "group-hover/checkbox:border-[color-mix(in_srgb,var(--foreground)_24%,transparent)]",
      active &&
        cn(
          "border-[var(--foreground)]",
          "shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
          "dark:shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_14%,transparent)]",
      ),
      error && "border-red-500/55",
      disabled && "cursor-not-allowed opacity-40",
      controlSizes[checkboxSize],
    );
  }

  return cn(
    "relative grid shrink-0 place-items-center rounded-[5px] border",
    smoothControlTransition,
    "border-[var(--border-strong)] bg-[var(--background)]",
    "shadow-[0_1px_1px_rgba(0,0,0,0.04),0_0_0_1px_rgba(0,0,0,0.02)]",
    "dark:shadow-[0_1px_2px_rgba(0,0,0,0.32),0_0_0_1px_rgba(255,255,255,0.04)]",
    focusRing,
    !disabled &&
      "group-hover/checkbox:border-[color-mix(in_srgb,var(--foreground)_26%,transparent)]",
    active &&
      cn(
        "border-[var(--foreground)] bg-[var(--foreground)]",
        "shadow-[0_1px_2px_rgba(0,0,0,0.12),0_0_0_1px_rgba(0,0,0,0.04)]",
        "dark:shadow-[0_1px_3px_rgba(0,0,0,0.45),0_0_0_1px_rgba(255,255,255,0.08)]",
    ),
    error && "border-red-500/55",
    disabled && "cursor-not-allowed opacity-40",
    controlSizes[checkboxSize],
  );
}

function CheckboxMark({
  variant,
  checked,
  indeterminate,
  checkboxSize,
}: {
  variant: CheckboxVariant;
  checked: boolean;
  indeterminate: boolean;
  checkboxSize: CheckboxSize;
}) {
  const active = checked || indeterminate;

  if (variant === "toggle") {
    return (
      <span
        aria-hidden="true"
        className={cn(
          "pointer-events-none rounded-full bg-white",
          "shadow-[0_1px_2px_rgba(0,0,0,0.18),0_0_0_1px_rgba(0,0,0,0.04)]",
          "transform-gpu transition-[transform,box-shadow,background-color] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none",
          "dark:bg-neutral-100 dark:shadow-[0_1px_3px_rgba(0,0,0,0.55),0_0_0_1px_rgba(255,255,255,0.08)]",
          active &&
            "shadow-[0_1px_3px_rgba(0,0,0,0.22),0_0_0_1px_rgba(0,0,0,0.06)]",
          checked
            ? knobCheckedTravel[checkboxSize]
            : indeterminate
              ? knobIndeterminateTravel[checkboxSize]
              : "translate-x-0",
          knobSizes[checkboxSize],
        )}
      />
    );
  }

  if (variant === "dot") {
    return (
      <span
        aria-hidden="true"
        className={cn(
          "rounded-full bg-[var(--foreground)]",
          "transform-gpu",
          smoothMarkTransition,
          "opacity-0 scale-[0.35]",
          active && "opacity-100 scale-100",
          checkboxSize === "sm" && "size-1.5",
          checkboxSize === "md" && "size-[7px]",
          checkboxSize === "lg" && "size-2",
        )}
      />
    );
  }

  if (indeterminate) {
    return (
      <span
        aria-hidden="true"
        className={cn(
          "rounded-full transform-gpu",
          smoothMarkTransition,
          "opacity-100 scale-100",
          variant === "classic"
            ? "bg-[var(--background)]"
            : "bg-[var(--foreground)]",
          checkboxSize === "sm" && "h-0.5 w-2",
          checkboxSize === "md" && "h-0.5 w-2.5",
          checkboxSize === "lg" && "h-[3px] w-3",
        )}
      />
    );
  }

  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className={cn(
        "transform-gpu",
        smoothMarkTransition,
        "opacity-0",
        checked && "opacity-100",
        checkboxSize === "sm" && "size-2.5",
        checkboxSize === "md" && "size-3",
        checkboxSize === "lg" && "size-3.5",
        variant === "classic"
          ? "text-[var(--background)]"
          : "text-[var(--foreground)]",
      )}
    >
      <path
        d="M3.25 8.1 6.35 11.2 12.75 4.6"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        className="transition-[stroke-dashoffset] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
        style={{
          strokeDasharray: 1,
          strokeDashoffset: checked ? 0 : 1,
        }}
      />
    </svg>
  );
}

export const Checkbox = React.forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      id,
      className,
      containerClassName,
      controlClassName,
      labelClassName,
      descriptionClassName,
      label,
      description,
      error,
      checkboxSize = "md",
      variant = "classic",
      fullWidth = true,
      checked,
      defaultChecked = false,
      disabled,
      onCheckedChange,
      onChange,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const reactId = React.useId();
    const checkboxId = id ?? `checkbox-${reactId}`;
    const descriptionId = description ? `${checkboxId}-description` : undefined;
    const errorId = error ? `${checkboxId}-error` : undefined;
    const inputRef = React.useRef<HTMLInputElement | null>(null);
    const isControlled = checked !== undefined;
    const [uncontrolledChecked, setUncontrolledChecked] =
      React.useState<CheckboxCheckedState>(defaultChecked);
    const currentChecked = isControlled ? checked : uncontrolledChecked;
    const isChecked = currentChecked === true;
    const isIndeterminate = currentChecked === "indeterminate";
    const describedBy =
      [ariaDescribedBy, errorId, descriptionId].filter(Boolean).join(" ") ||
      undefined;

    const setRefs = React.useCallback(
      (node: HTMLInputElement | null) => {
        inputRef.current = node;
        if (typeof ref === "function") {
          ref(node);
        } else if (ref) {
          ref.current = node;
        }
      },
      [ref],
    );

    React.useLayoutEffect(() => {
      if (inputRef.current) inputRef.current.indeterminate = isIndeterminate;
    }, [isIndeterminate]);

    const handleChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        const nextChecked = event.currentTarget.checked;
        if (!isControlled) setUncontrolledChecked(nextChecked);
        onCheckedChange?.(nextChecked, event);
        onChange?.(event);
      },
      [isControlled, onChange, onCheckedChange],
    );

    return (
      <label
        data-checkbox=""
        data-state={
          isIndeterminate ? "indeterminate" : isChecked ? "checked" : "unchecked"
        }
        data-disabled={disabled ? "" : undefined}
        data-error={error ? "" : undefined}
        className={cn(
          "group/checkbox relative flex cursor-pointer select-none items-start",
          rowGap[checkboxSize],
          fullWidth ? "w-full" : "w-fit",
          disabled && "cursor-not-allowed",
          containerClassName,
          className,
        )}
      >
        <input
          ref={setRefs}
          id={checkboxId}
          type="checkbox"
          checked={isChecked}
          disabled={disabled}
          aria-checked={isIndeterminate ? "mixed" : isChecked}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={handleChange}
          className="peer sr-only"
          {...props}
        />
        <span
          className={cn(
            controlOffset[checkboxSize],
            getControlClasses({
              variant,
              checked: isChecked,
              indeterminate: isIndeterminate,
              disabled,
              error,
              checkboxSize,
            }),
            controlClassName,
          )}
        >
          <CheckboxMark
            variant={variant}
            checked={isChecked}
            indeterminate={isIndeterminate}
            checkboxSize={checkboxSize}
          />
        </span>

        {label || description || error ? (
          <span className="min-w-0 flex-1 pt-px">
            {label ? (
              <span
                className={cn(
                  "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
                  labelSizes[checkboxSize],
                  disabled && "text-[var(--muted-foreground)]",
                  labelClassName,
                )}
              >
                {label}
              </span>
            ) : null}
            {description ? (
              <span
                id={descriptionId}
                className={cn(
                  "mt-1 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                  descriptionClassName,
                )}
              >
                {description}
              </span>
            ) : null}
            {error ? (
              <span
                id={errorId}
                className="mt-1.5 block text-[12px] leading-[1.45] font-medium text-red-600 dark:text-red-400"
              >
                {error}
              </span>
            ) : null}
          </span>
        ) : null}
      </label>
    );
  },
);

Checkbox.displayName = "Checkbox";

export function CheckboxGroup({
  label,
  description,
  error,
  children,
  className,
  ...props
}: CheckboxGroupProps) {
  const reactId = React.useId();
  const descriptionId = description
    ? `checkbox-group-${reactId}-description`
    : undefined;
  const errorId = error ? `checkbox-group-${reactId}-error` : undefined;

  return (
    <fieldset
      aria-describedby={[descriptionId, errorId].filter(Boolean).join(" ") || undefined}
      className={cn("space-y-3.5", className)}
      {...props}
    >
      {label || description ? (
        <div className="space-y-1">
          {label ? (
            <legend className="text-sm font-semibold tracking-[-0.015em] text-[var(--foreground)]">
              {label}
            </legend>
          ) : null}
          {description ? (
            <p
              id={descriptionId}
              className="text-[12px] leading-[1.45] text-[var(--muted-foreground)]"
            >
              {description}
            </p>
          ) : null}
        </div>
      ) : null}
      <div className="space-y-1">{children}</div>
      {error ? (
        <p
          id={errorId}
          className="text-[12px] leading-[1.45] font-medium text-red-600 dark:text-red-400"
        >
          {error}
        </p>
      ) : null}
    </fieldset>
  );
}

export function CheckboxCard({
  leading,
  trailing,
  className,
  containerClassName,
  checkboxSize = "md",
  variant = "soft",
  id,
  disabled,
  ...props
}: CheckboxCardProps) {
  const reactId = React.useId();
  const checkboxId = id ?? `checkbox-card-${reactId}`;

  return (
    <div
      className={cn(
        "group/checkbox-card rounded-xl border border-[var(--border)] bg-[var(--surface)]",
        "transition-[border-color,background-color,box-shadow] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)]",
        "shadow-[0_1px_1px_rgba(0,0,0,0.03),0_1px_2px_rgba(0,0,0,0.04)]",
        "dark:shadow-[0_1px_2px_rgba(0,0,0,0.32)]",
        "has-[[data-state=checked]]:border-[color-mix(in_srgb,var(--foreground)_18%,transparent)]",
        "has-[[data-state=checked]]:bg-[color-mix(in_srgb,var(--foreground)_2.5%,var(--surface))]",
        "has-[[data-state=checked]]:shadow-[0_1px_2px_rgba(0,0,0,0.05),0_0_0_1px_color-mix(in_srgb,var(--foreground)_6%,transparent)]",
        "dark:has-[[data-state=checked]]:shadow-[0_1px_3px_rgba(0,0,0,0.38),0_0_0_1px_color-mix(in_srgb,var(--foreground)_10%,transparent)]",
        !disabled &&
          "hover:border-[color-mix(in_srgb,var(--foreground)_14%,transparent)] hover:bg-[color-mix(in_srgb,var(--foreground)_1.5%,var(--surface))]",
        disabled &&
          "cursor-not-allowed opacity-50 hover:border-[var(--border)] hover:bg-[var(--surface)]",
        className,
      )}
    >
      <div className="flex items-start gap-3 p-4">
        {leading ? (
          <div
            className={cn(
              "mt-0.5 grid size-9 shrink-0 place-items-center rounded-lg border border-[var(--border)]",
              "bg-[color-mix(in_srgb,var(--foreground)_3%,var(--surface))] text-[var(--muted-foreground)]",
              "transition-[border-color,background-color,color] duration-200",
              "group-has-[[data-state=checked]]/checkbox-card:border-[color-mix(in_srgb,var(--foreground)_14%,transparent)]",
              "group-has-[[data-state=checked]]/checkbox-card:bg-[color-mix(in_srgb,var(--foreground)_7%,var(--surface))]",
              "group-has-[[data-state=checked]]/checkbox-card:text-[var(--foreground)]",
              "[&_svg]:size-[17px]",
            )}
          >
            {leading}
          </div>
        ) : null}
        <Checkbox
          {...props}
          id={checkboxId}
          disabled={disabled}
          checkboxSize={checkboxSize}
          variant={variant}
          containerClassName={cn("flex-1", containerClassName)}
        />
        {trailing ? (
          <div className="shrink-0 pt-0.5">
            <span className="inline-flex items-center rounded-md border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--surface))] px-2 py-0.5 text-[11px] font-medium tracking-[0.01em] text-[var(--muted-foreground)]">
              {trailing}
            </span>
          </div>
        ) : null}
      </div>
    </div>
  );
}
